  const stop=(reason)=>{result.status='UNVERIFIABLE';result.limitations.push(reason);return result;};
  if(!manifest||typeof manifest!=='object'||Array.isArray(manifest)) return stop('요청서 JSON을 읽지 못했습니다.');
  if(manifest.artwork_id!==context.artwork_id) return stop('메일의 원화 ID와 요청서의 원화 ID가 다릅니다.');
  result.baseline_revision=manifest.baseline_revision||null;
  if(manifest.baseline_filename!==`${context.artwork_id}_BASELINE.pdf`) return stop('요청서의 기준본 파일명과 검색 규칙이 일치하지 않습니다.');
  if(!Array.isArray(manifest.requests)||!Array.isArray(manifest.protected_values)) return stop('요청서에 requests와 protected_values 배열이 필요합니다.');
  if(!manifest.requests.length) return stop('등록된 수정 요청이 없습니다. 변경 유무만으로 수정 적정성을 확정할 수 없습니다.');
  if(manifest.requests.length>30||manifest.protected_values.length>30) return stop('요청/유지 항목은 각각 30건 이하로 나누어 주세요.');
