  if(beforeN.length>30000||afterN.length>30000) return stop('각 문서 30,000자 이하만 비교합니다. 일부만 잘라 정상 판정하지 않습니다.');
  const marker=String(manifest.baseline_artwork_marker||context.artwork_id);
  if(!beforeN.includes(marker)||!afterN.includes(marker)) return stop('기준본 또는 수정본에서 원화 식별 표기를 확인하지 못했습니다. 다른 제품인지 확인하세요.');
  if(context.before_pages>10||context.after_pages>10) return stop('10쪽을 초과한 PDF입니다. 이번 교육용 범위를 벗어나므로 나누어 확인하세요.');
  const requestSpans=[];
