      else if(remainingCount===1&&newAfter===newBefore) {status='NOT_APPLIED';reason='기존 문구가 남아 있고 요청한 새 문구의 추가가 확인되지 않습니다.';}
      else {status='NEEDS_REVIEW';reason='일부 변경 또는 중복 문구가 있어 요청대로 수정됐는지 단정할 수 없습니다.';}
