    result.request_checks.push({id:r.id,owner:r.owner||null,label:r.label||r.id,type:r.type,before:r.before,expected_after:r.type==='remove'?'(삭제)':r.after,status,reason,before_occurrences:beforeCount,remaining_occurrences:remainingCount});
