const statusMap={APPLIED:'반영 확인',NOT_APPLIED:'미반영',NEEDS_REVIEW:'사람 확인',KEPT:'유지 확인',PROTECTED_CHANGED:'유지 항목 변경',POSSIBLE_REVERSION:'이전 수정 원복 가능성'};
const badge=report.status==='UNVERIFIABLE'?'검수 불가 / 확인 필요':report.status==='TEXT_CHECK_COMPLETE'?'요청 문구 반영 확인 · 디자인 미검수':'재확인 필요';
function table(headers,rows){return `<table style="border-collapse:collapse;width:100%;font-size:13px"><tr>${headers.map(h=>`<th style="border:1px solid #ccd3d4;padding:9px;text-align:left;background:#eef2f0">${e(h)}</th>`).join('')}</tr>${rows.map(r=>'<tr>'+r.map(c=>`<td style="border:1px solid #ccd3d4;padding:9px;vertical-align:top;white-space:pre-wrap">${e(c)}</td>`).join('')+'</tr>').join('')}</table>`;}
let body=`<div style="font-family:Arial,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;max-width:900px;color:#1d3338"><div style="background:#16353b;color:white;padding:24px"><div style="font-size:32px;font-weight:800">FINAL?</div><p style="margin:4px 0">Is this really the final version?</p></div><h2>${e(badge)}</h2><p><b>${e(ctx.artwork_id)}</b> · 테스트/요청 식별자 ${e(ctx.test_id)}<br>수정본: ${e(ctx.after_filename)}<br>기준본: ${e(ctx.baseline_file?.name||'확인 전')}<br>기준 표시: ${e(report.baseline_revision||'확인 전')}</p>`;
if(report.limitations?.length)body+='<h3>확인이 필요한 이유</h3><p>'+report.limitations.map(e).join('<br>')+'</p>';
if(report.summary)body+=`<p>요청 ${report.summary.requests_total}건 중 ${report.summary.requests_applied}건 반영 확인 / 미해결 ${report.summary.requests_unresolved}건 / 유지 항목 이상 ${report.summary.protected_issues}건 / 미요청 변경 후보 ${report.summary.unexpected_change_groups}묶음</p>`;
if(report.request_checks.length)body+='<h3>1. 수정 요청 대조</h3>'+table(['항목','요청 내용','판정 / 근거'],report.request_checks.map(x=>[x.id+' '+x.label,x.before+' → '+x.expected_after,(statusMap[x.status]||x.status)+'\n'+x.reason]));
if(report.protected_checks.length)body+='<h3>2. 유지해야 할 정보</h3>'+table(['항목','기준 문구','판정 / 근거'],report.protected_checks.map(x=>[x.id+' '+x.label,x.text,(statusMap[x.status]||x.status)+'\n'+x.reason]));
if(report.changes.length)body+='<h3>3. 실제 Before / After 문자 변화</h3>'+table(['근거 ID','이전','수정','주변 문맥'],report.changes.map(x=>[x.id,x.before||'(없음)',x.after||'(삭제)',x.context_before+' … '+x.context_after]));
if(report.unexpected_changes.length)body+='<h3>4. 등록 요청으로 설명되지 않는 변경 후보</h3>'+table(['근거 ID','이전','수정'],report.unexpected_changes.map(x=>[x.id,x.before||'(없음)',x.after||'(삭제)']));
if(ai)body+='<h3>AI 설명 초안 · 사람 검토 필요</h3><p>'+e(ai.summary)+'</p><h3>원화사 재확인 문안 초안 · 자동 발송하지 않음</h3><p style="white-space:pre-wrap">'+e(ai.followup_draft)+'</p><p>참조: '+e(ai.evidence_ids.join(', '))+'</p>';
else body+='<h3>AI 상태</h3><p>'+e(ai_problem||'이번 실행에서는 AI를 호출하지 않았습니다.')+'</p>';
body+='<h3>검수 범위와 원가</h3><p>'+report.warnings.map(e).join('<br>')+'</p>';
body+=`<p>Execution ID: ${e(ctx.execution_id)}<br>입력 토큰: ${inp===null?'미측정':inp} / 출력 토큰: ${out===null?'미측정':out} / 입력 중 캐시: ${apiUsage?cached:'미측정'}<br>API 비용: ${cost===null?'미계산: 단가/usage 확인 필요':('$'+cost.toFixed(8))}<br>서버비 및 사람 검수시간은 별도입니다. 본 메일의 발송 자체가 최종 승인 또는 정확성 보증은 아닙니다.</p></div>`;
const filename=`FINAL_${ctx.artwork_id}_${ctx.test_id}_${String(ctx.execution_id).replace(/[^A-Za-z0-9_-]/g,'')}.json`;
const binary=await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(report,null,2),'utf8'),filename,'application/json');
return {json:{report_to:ctx.report_to,source_message_id:ctx.source_message_id,subject:`FINALRESULT | ${ctx.artwork_id} | ${ctx.test_id} | ${badge}`,html:body,audit:report},binary:{audit_report:binary}};

const prepared=$('17 Compose Report').item.json;
const sent=$('18 Send Result to Me').item.json;
const audit=JSON.parse(JSON.stringify(prepared.audit));
audit.delivery={status:sent.id?'SENT_ACCEPTED_BY_GMAIL':'DELIVERY_RESPONSE_REQUIRES_CHECK',gmail_result_id:sent.id||null,recipient:prepared.report_to,label_status:$json.error?'FAILED':'ATTEMPTED',label_error:$json.error||null};
audit.execution.finished_at=new Date().toISOString();
audit.execution.total_seconds=(Date.now()-new Date(audit.execution.started_at).getTime())/1000;
return {json:audit};

const ctx=$json;
const report={schema_version:'1.0',brand:'FINAL?',scope:'extractable_text_only',status:'UNVERIFIABLE',final_approval:false,artwork_id:ctx.artwork_id,comparison_complete:false,request_checks:[],protected_checks:[],changes:[],unexpected_changes:[],warnings:['이 메일은 검수 완료 통지가 아니라 입력·연결 확인 요청입니다.'],limitations:ctx.error_messages||['입력 확인 필요'],source:{gmail_message_id:ctx.source_message_id,subject:ctx.source_subject,after_filename:ctx.after_filename},execution:{id:ctx.execution_id,started_at:ctx.started_at}};
return {json:{...ctx,report,use_ai:false}};
